  obj->PPDDStruct.breaks[1] = pp_breaks[1];
  obj->PPDStruct.breaks[2] = pp_breaks[2];
  obj->PPDDStruct.breaks[2] = pp_breaks[2];
  obj->PPDStruct.breaks[3] = pp_breaks[3];
