// Function for MATLAB Function: '<S181>/VariableHorizonOptimizer'
int32_T proc_control::proc_control_xpotrf(int32_T n, real_T b_A_data[], int32_T
  lda)
{
  int32_T info;
  boolean_T exitg1;
  info = 0;
  proc_control_B.j_c = 0;
  exitg1 = false;
  while ((!exitg1) && (proc_control_B.j_c <= static_cast<uint8_T>(n) - 1)) {
    int32_T b_k;
    proc_control_B.idxAjj = proc_control_B.j_c * lda + proc_control_B.j_c;
    proc_control_B.ssq = 0.0;
    if (proc_control_B.j_c >= 1) {
      for (b_k = 0; b_k < proc_control_B.j_c; b_k++) {
        proc_control_B.c_b = b_A_data[b_k * lda + proc_control_B.j_c];
        proc_control_B.ssq += proc_control_B.c_b * proc_control_B.c_b;
      }
    }

    proc_control_B.ssq = b_A_data[proc_control_B.idxAjj] - proc_control_B.ssq;
    if (proc_control_B.ssq > 0.0) {
      proc_control_B.ssq = std::sqrt(proc_control_B.ssq);
      b_A_data[proc_control_B.idxAjj] = proc_control_B.ssq;
      if (proc_control_B.j_c + 1 < n) {
        proc_control_B.b_iy_b = (n - proc_control_B.j_c) - 1;
        if ((proc_control_B.b_iy_b != 0) && (proc_control_B.j_c != 0)) {
          proc_control_B.ix_l = proc_control_B.j_c;
          proc_control_B.b_l = ((proc_control_B.j_c - 1) * lda +
                                proc_control_B.j_c) + 2;
          for (b_k = proc_control_B.j_c + 2; lda < 0 ? b_k >= proc_control_B.b_l
               : b_k <= proc_control_B.b_l; b_k += lda) {
            proc_control_B.c_b = -b_A_data[proc_control_B.ix_l];
            proc_control_B.d_j = (b_k + proc_control_B.b_iy_b) - 1;
            for (proc_control_B.b_ix_f = b_k; proc_control_B.b_ix_f <=
                 proc_control_B.d_j; proc_control_B.b_ix_f++) {
              int32_T tmp;
              tmp = ((proc_control_B.idxAjj + proc_control_B.b_ix_f) - b_k) + 1;
              b_A_data[tmp] += b_A_data[proc_control_B.b_ix_f - 1] *
                proc_control_B.c_b;
            }

            proc_control_B.ix_l += lda;
          }
        }

        proc_control_B.ssq = 1.0 / proc_control_B.ssq;
        b_k = proc_control_B.idxAjj + proc_control_B.b_iy_b;
        for (proc_control_B.b_ix_f = proc_control_B.idxAjj + 2;
             proc_control_B.b_ix_f <= b_k + 1; proc_control_B.b_ix_f++) {
          b_A_data[proc_control_B.b_ix_f - 1] *= proc_control_B.ssq;
        }
      }

      proc_control_B.j_c++;
    } else {
      b_A_data[proc_control_B.idxAjj] = proc_control_B.ssq;
      info = proc_control_B.j_c + 1;
      exitg1 = true;
    }
  }

  return info;
}

