      e = (beta1 + obj_nvar) - 1;
      for (int32_T ia{beta1}; ia <= e; ia++) {
        int32_T tmp;
        tmp = ia - beta1;
        workspace_data[tmp] += H[ia - 1] * proc_control_B.c_l;
      }

      ix++;
