  liveliness_lease_duration.sec = sec;

  // Start for MATLABSystem: '<S18>/SinkBlock' incorporates:
  //   MATLABSystem: '<S185>/SinkBlock'

  liveliness_lease_duration.nsec = (input - sec) * 1.0E+9;
